return batches;

function clasificar(titulo, descripcion, tags) {

  //  para recorta la descripcion para evitar ruido
  const descCorta = (descripcion || '').slice(0, 300);

  // convierte tags en texto
  const tagsTexto = Array.isArray(tags)
    ? tags.join(' ')
    : (tags || '');

  // version limpia del titulo
  const t = normalizar(titulo || '');

  // esto junta todo el contenido del video
  const texto = normalizar(
    `${titulo || ''} ${descCorta} ${tagsTexto}`
  );

  // el orden importa por lo que primero reglas especificas y luego generales
  if (esComercialOpositaInstitucional(t)) return 'Información comercial/institucional';
  if (esConvocatoria(t, texto))           return 'Información sobre convocatorias';
  if (esClaseTemario(t, texto))           return 'Clase/Temario';
  if (esConsejosPrioritarios(t))          return 'Consejos para opositar';
  if (esMetodologia(t, texto))            return 'Metodología para opositar';
  if (esTestimonio(t, texto))             return 'Testimonio';
  if (esComercial(t, texto))              return 'Información comercial/institucional';
  if (esPsicologia(t, texto))             return 'Psicología del opositor';
  if (esFallos(t, texto))                 return 'Fallos al opositar';
  if (esPlanificacion(t, texto))          return 'Planificación de estudio';
  if (esTecnicasEstudio(t, texto))        return 'Técnicas de estudio';
  if (esConsejos(t, texto))               return 'Consejos para opositar';

  // fallback final
  return 'Sin clasificar';
}



// // para limpira el texto minusculas, sin tildes y sin simbolos raros
function normalizar(texto) {
  return (texto || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^\w\sñ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}


// busca una palabra exacta y evita errores 
function contiene(texto, palabra) {
  return new RegExp(`\\b${palabra}\\b`, 'i').test(texto);
}


// cuenta coincidencias
function cuenta(texto, palabras) {

  let n = 0;

  for (const p of palabras) {
    if (contiene(texto, p)) n++;
  }

  return n;
}


// detecta videos comerciales de oposita
function esComercialOpositaInstitucional(t) {

  // comprueba si aparece la marca
  const marca =
    contiene(t, 'opositafp') ||
    /oposita\s+(fp|primaria|secundaria)/.test(t) ||
    contiene(t, 'oposita primaria');

  if (!marca) return false;

  // frases promocionales tipicas
  if (contiene(t, 'te preparamos')) return true;
  if (contiene(t, 'asi te preparamos')) return true;
  if (contiene(t, 'quien te prepara')) return true;

  // casos mas concretos
  if (contiene(t, 'funcionarios') &&
      contiene(t, 'exmiembros')) {
    return true;
  }

  return false;
}


// detecta contenido sobre convocatorias
function esConvocatoria(t, texto) {

  // palabras frecuentes
  if (contiene(t, 'convocatoria')) return true;
  if (contiene(t, 'convocatorias')) return true;

  // detecta cosas tipo "300 plazas"
  if (/\b\d+\s+plazas?\b/.test(t)) {
    return true;
  }

  if (contiene(t, 'baremo')) return true;

  // relacion provincia + año + oposiciones
  const provincias =
    /\b(andalucia|madrid|murcia|galicia|cantabria|valencia)\b/;

  const tieneProvincia = provincias.test(t);
  const tieneAño = /\b(2025|2026|2027)\b/.test(t);

  if (tieneProvincia &&
      tieneAño &&
      contiene(t, 'oposiciones')) {
    return true;
  }

  return false;
}


// detecta clases y temario
function esClaseTemario(t, texto) {

  const keywords = [
    'discapacidad',
    'alumnado',
    'neae',
    'lomloe',
    'atencion a la diversidad'
  ];

  // con una keyword ya basta
  if (cuenta(t, keywords) >= 1) {
    return true;
  }

  return false;
}


// consejos muy concretos
function esConsejosPrioritarios(t) {

  // titulos tipo "el secreto que nadie cuenta"
  if (contiene(t, 'secreto') &&
      contiene(t, 'nadie')) {
    return true;
  }

  return false;
}


// contenido metodologico
function esMetodologia(t, texto) {

  // estrategias de preparacion
  if (contiene(t, 'hilo conductor') &&
      !contiene(t, 'secreto')) {
    return true;
  }

  // supuestos practicos
  if (contiene(t, 'supuesto practico') &&
      contiene(t, 'caso real')) {
    return true;
  }

  return false;
}


// testimonios y experiencias personales
function esTestimonio(t, texto) {

  // muchos videos de oposita son testimoniales
  const marcaOposita =
    contiene(t, 'opositafp') ||
    /oposita\s+fp/.test(t) ||
    /oposita\s+secundaria/.test(t) ||
    /oposita\s+primaria/.test(t);

  if (marcaOposita) return true;

  // frases tipicas
  if (contiene(t, 'testimonio')) return true;
  if (/yo\s+gane\s+mi\s+plaza/.test(t)) return true;

  // experiencias personales
  if (/\bmi\s+experiencia\s+real/.test(t)) return true;
  if (/\bmi\s+primera\s+vez\b/.test(t)) return true;

  return false;
}


// contenido promocional general
function esComercial(t, texto) {

  // academias y preparacion
  if (/\bacademia\s+(online\s+)?(de\s+)?oposiciones?\b/.test(t)) {
    return true;
  }

  // matriculas y promociones
  if (contiene(t, 'plazo de matricula')) return true;
  if (contiene(t, 'abierto plazo')) return true;

  return false;
}


// contenido emocional o mental
function esPsicologia(t, texto) {

  const keywords = [
    'cerebro',
    'mente',
    'ansiedad',
    'procrastinas',
    'desconecta'
  ];

  if (cuenta(t, keywords) >= 1) {
    return true;
  }

  return false;
}


// errores frecuentes al opositar
function esFallos(t, texto) {

  // detecta "errores", "fallos", etc
  if (/\b(error|errores)\b/.test(t)) {
    return true;
  }

  // frases negativas
  if (contiene(t, 'nunca debes')) return true;
  if (contiene(t, 'no debes hacer')) return true;

  return false;
}


// organizacion y planificacion
function esPlanificacion(t, texto) {

  if (contiene(t, 'agenda')) return true;
  if (contiene(t, 'compaginar')) return true;
  if (contiene(t, 'organizar')) return true;

  // evita confundir con "rutina de campeones"
  if (contiene(t, 'rutina') &&
      !contiene(t, 'campeones')) {
    return true;
  }

  return false;
}


// tecnicas de estudio
function esTecnicasEstudio(t, texto) {

  // tecnicas concretas
  if (contiene(t, 'tecnica') &&
      (contiene(t, 'repaso') ||
       contiene(t, 'estudio') ||
       contiene(t, 'memoria'))) {
    return true;
  }

  return false;
}


// categoria general de consejos
function esConsejos(t, texto) {

  if (contiene(t, 'consejos')) return true;
  if (contiene(t, 'guia')) return true;

  // contenido tipo "como aprobar oposiciones"
  if (contiene(t, 'como aprobar') &&
      contiene(t, 'oposiciones')) {
    return true;
  }

  return false;
}


// obtiene todos los items de n8n
const items = $input.all();

const resultado = [];

for (const item of items) {

  // datos del video
  const v = item.json || {};

  // intenta leer titulo plano o snippet
  const titulo =
    v.title ||
    (v.snippet && v.snippet.title) ||
    '';

  // descripcion del video
  const descripcion =
    v.description ||
    (v.snippet && v.snippet.description) ||
    '';

  // tags del video
  const tags =
    v.tags ||
    (v.snippet && v.snippet.tags) ||
    [];

  // clasifica contenido
  const categoria =
    clasificar(titulo, descripcion, tags);

  // añade nueva propiedad
  resultado.push({
    json: {
      ...v,
      categoriaContenido: categoria
    }
  });
}

// devuelve array final a n8n
return resultado;
